/** Saved phone copies only; watch history and library entries are never removed. */
final class PhoneDownloadsManage {
 static {String[][] words={
 {"Free up space","تحرير مساحة"},{"Recent","الأحدث"},{"Name","الاسم"},{"Size","الحجم"},{"Sort","ترتيب"},{"Movies","الأفلام"},{"Delete season","حذف الموسم"},{"Delete show","حذف المسلسل"},{"Delete watched","حذف ما شاهدته"},{"Delete","حذف"},{"Delete saved videos?","حذف الفيديوهات المحفوظة؟"},{"%d videos · %s","%d فيديوهات · %s"},{"%d watched","%d مشاهد"},{"Season %d","الموسم %d"},{"%s, %d episodes, %s","%s، %d حلقات، %s"},{"Deletes permanently. Poster and watch history stay.","حذف نهائي. تبقى الصورة وسجل المشاهدة."},{"Freed %s","تم تحرير %s"},{"Delete %s","حذف %s"},{"Watched episodes (older than 7 days)","حلقات مشاهدة (منذ أكثر من ٧ أيام)"},{"Finished shows","مسلسلات مكتملة المشاهدة"},{"Leftover partial downloads","بقايا تنزيلات جزئية"},{"Torrents only sharing back","تورنت يشارك مع الآخرين فقط"},{"Stop sharing, keep file","إيقاف المشاركة مع الاحتفاظ بالملف"},{"Saved on: %s ▾","محفوظ على: %s ▾"},{"Phone storage","مساحة الهاتف"},{"SD card","بطاقة SD"},{"Move to SD card","نقل إلى بطاقة SD"},{"Move to phone storage","نقل إلى مساحة الهاتف"},{"Default download storage","مساحة التنزيل الافتراضية"},{"Download storage options","خيارات مساحة التنزيل"},{"Choose phone storage or an SD card.","اختر مساحة الهاتف أو بطاقة SD."},{"Storage is unavailable. Reinsert the SD card and try again.","المساحة غير متاحة. أعد إدخال بطاقة SD ثم حاول مجددًا."},{"Wait for this download to finish before moving it.","انتظر اكتمال التنزيل قبل نقله."},{"Not enough space. Free some space on the destination and try again.","المساحة غير كافية. حرر مساحة في الوجهة ثم حاول مجددًا."},{"A file already exists at the destination.","يوجد ملف بالفعل في الوجهة."},{"Moved the video, but could not remove the original copy.","نُقل الفيديو ولكن تعذرت إزالة النسخة الأصلية."},{"Moving… %s / %s","جارٍ النقل… %s / %s"},{"Move complete","اكتمل النقل"},{"More options for %s","المزيد من الخيارات لـ %s"},{"No files to delete","لا توجد ملفات للحذف"},{"Some files could not be changed. Try again.","تعذر تغيير بعض الملفات. حاول مجددًا."},{"Cancel","إلغاء"},{"Play","تشغيل"}};for(String[] w:words)Loc.AR.put(w[0],w[1]);}
 static void words(){}
 final DataStore data;final DownloadStore store;
 PhoneDownloadsManage(DataStore d,DownloadStore s){data=d;store=s;}
 static String size(long n){return n<1024?Math.max(0,n)+" B":n<1048576?String.format(Locale.ROOT,"%.1f KB",n/1024d):PcDownloadsActivity.size(n);}
 static String ltr(String s){return "\u2066"+s+"\u2069";}
 static final class Saved {final JSONObject item,job;final File file;final long bytes,recent;Saved(JSONObject i,JSONObject j,File f){item=i;job=j;file=f;long n=0;for(File part:bundle(f))n+=part.length();bytes=n;recent=j.optLong("doneAt",f.lastModified());}String id(){return item.optString("id");}boolean watched(){return DataStore.watched(item);}}
 static final class Group {final String key,name;final List<Saved> files=new ArrayList<>();Group(String k,String n){key=k;name=n;}long bytes(){long n=0;for(Saved f:files)n+=f.bytes;return n;}long recent(){long n=0;for(Saved f:files)n=Math.max(n,f.recent);return n;}int watched(){int n=0;for(Saved f:files)if(f.watched())n++;return n;}Map<Integer,List<Saved>> seasons(){Map<Integer,List<Saved>> s=new TreeMap<>();for(Saved f:files)s.computeIfAbsent(f.item.optInt("season"),k->new ArrayList<>()).add(f);return s;}}
 List<Group> groups(String sort){Map<String,Group> groups=new LinkedHashMap<>();for(JSONObject j:DataStore.objects(store.jobs()))if(j.optString("status").equals("complete"))try{JSONObject i=data.item(j.optString("id"));if(i==null)continue;File f=store.file(j.optString("id"),false);if(!f.isFile()||Files.isSymbolicLink(f.toPath()))continue;String key=i.optBoolean("movie")?"movies":i.optString("group");Group g=groups.computeIfAbsent(key,k->new Group(k,k.equals("movies")?Loc.t("Movies"):i.optString("title")));g.files.add(new Saved(i,j,f));}catch(Exception ignored){}List<Group> result=new ArrayList<>(groups.values());for(Group g:result)g.files.sort(Comparator.comparingInt((Saved f)->f.item.optInt("season")).thenComparingInt(f->f.item.optInt("episode")));result.sort(sort.equals("Name")?Comparator.comparing(g->g.name.toLowerCase(Locale.ROOT)):sort.equals("Size")?Comparator.comparingLong(Group::bytes).reversed():Comparator.comparingLong(Group::recent).reversed());return result;}
 static List<File> bundle(File video){List<File> result=new ArrayList<>();if(video.isFile())result.add(video);String name=video.getName(),stem=name.contains(".")?name.substring(0,name.lastIndexOf('.')):name;File[] siblings=video.getParentFile().listFiles();if(siblings!=null)for(File f:siblings)if(f.isFile()&&!Files.isSymbolicLink(f.toPath())&&f.getName().startsWith(stem+".")&&f.getName().matches("(?i).*\\.(srt|ass|ssa|vtt|sub|idx)$"))result.add(f);return result;}
 static void deleteSubtitles(DataStore data,String id)throws IOException{JSONObject item=data.item(id);List<JSONObject> subs=new ArrayList<>(DataStore.objects(data.phoneSubtitles(id)));if(item!=null)subs.addAll(DataStore.objects(item.optJSONArray("subtitleFiles")));for(JSONObject sub:subs){File file=data.subtitle(sub);if(file==null||!file.isFile())continue;boolean shared=false;for(JSONObject other:DataStore.objects(data.items()))if(!other.optString("id").equals(id)){List<JSONObject> otherSubs=new ArrayList<>(DataStore.objects(other.optJSONArray("subtitleFiles")));otherSubs.addAll(DataStore.objects(data.phoneSubtitles(other.optString("id"))));for(JSONObject o:otherSubs)if(file.equals(data.subtitle(o)))shared=true;}if(!shared&&!file.delete())throw new IOException(Loc.t("Some files could not be changed. Try again."));}}
 static long bytes(File f){if(Files.isSymbolicLink(f.toPath()))return 0;if(f.isFile())return f.length();long n=0;File[] children=f.listFiles();if(children!=null)for(File child:children)n+=bytes(child);return n;}
 long delete(List<Saved> files,boolean watched)throws Exception{long freed=0;for(Saved f:files){if(!store.file(f.id(),false).getCanonicalFile().equals(f.file.getCanonicalFile()))throw new IOException(Loc.t("Phone profile changed"));JSONObject current=data.item(f.id());if(watched&&(current==null||!DataStore.watched(current)))continue;long before=0;for(File part:bundle(store.file(f.id(),false)))before+=part.length();store.remove(f.id());freed+=before;}return freed;}
 static long watchedAt(JSONObject item){long at=0;for(JSONObject v:DataStore.objects(item.optJSONArray("viewings"))){if(v.optBoolean("dateUnknown"))return 0;at=Math.max(at,DataStore.date(v.optString("watchedAt")));}JSONObject p=item.optJSONObject("progress");if(at==0&&p!=null&&p.optBoolean("completed"))at=Math.max(at,DataStore.date(p.optString("updatedAt")));return at;}
 static final class Suggestion {final String kind;final List<Saved> files=new ArrayList<>();final List<File> leftovers=new ArrayList<>();final List<String> sharing=new ArrayList<>();Suggestion(String k){kind=k;}long bytes(){long n=0;for(Saved f:files)n+=f.bytes;for(File f:leftovers)n+=PhoneDownloadsManage.bytes(f);return n;}}
 List<Suggestion> suggestions(long now){Map<String,Suggestion> result=new LinkedHashMap<>();for(String k:new String[]{"Watched episodes (older than 7 days)","Finished shows","Leftover partial downloads","Torrents only sharing back"})result.put(k,new Suggestion(k));Set<String> hashes=new HashSet<>(),liveParts=new HashSet<>();for(JSONObject j:DataStore.objects(store.jobs())){hashes.add(j.optString("hash"));try{if(!Arrays.asList("failed","cancelled","complete").contains(j.optString("status")))liveParts.add(store.file(j.optString("id"),true).getCanonicalPath());}catch(Exception ignored){}if(j.optString("status").equals("complete")&&j.optString("torrentMessage").equals("Sharing back"))result.get("Torrents only sharing back").sharing.add(j.optString("id"));}
  for(Group g:groups("Name")){List<JSONObject> all=g.files.isEmpty()?List.of():data.episodes(g.files.get(0).item);boolean finished=!g.key.equals("movies")&&!all.isEmpty();for(JSONObject e:all)if(e.optInt("season")>0&&PhoneSeasonPlan.released(e,now)&&!DataStore.watched(e))finished=false;for(Saved f:g.files)if(!f.watched())finished=false;
   for(Saved f:g.files)if(finished)result.get("Finished shows").files.add(f);else if(!f.item.optBoolean("movie")&&f.watched()&&watchedAt(f.item)>0&&watchedAt(f.item)<now-7L*86400000)result.get("Watched episodes (older than 7 days)").files.add(f);
  }
  Suggestion left=result.get("Leftover partial downloads");for(File dir:store.storageDirectories()){File[] files=dir.listFiles();if(files!=null)for(File f:files)try{if(f.isFile()&&f.getName().endsWith(".part")&&!liveParts.contains(f.getCanonicalPath()))left.leftovers.add(f);}catch(Exception ignored){}File[] torrents=new File(dir,".torrents").listFiles();if(torrents!=null)for(File f:torrents)if(f.isDirectory()&&!Files.isSymbolicLink(f.toPath())&&!hashes.contains(f.getName()))left.leftovers.add(f);}
  return new ArrayList<>(result.values());
 }
 long free(List<Suggestion> chosen)throws Exception{long freed=0;for(Suggestion s:chosen){freed+=delete(s.files,false);for(String id:s.sharing){JSONObject j=store.job(id);if(j!=null&&j.optString("status").equals("complete")){store.torrents.stop(id,false);store.torrentMessage(id,"");}}for(File f:s.leftovers){boolean safe=false;for(Suggestion fresh:suggestions(System.currentTimeMillis()))if(fresh.leftovers.contains(f))safe=true;if(!safe)continue;long n=bytes(f);erase(f);freed+=n;}}return freed;}
 static void erase(File f)throws IOException{if(Files.isSymbolicLink(f.toPath()))throw new IOException("Invalid download storage");File[] children=f.listFiles();if(children!=null)for(File child:children)erase(child);if(f.exists()&&!f.delete())throw new IOException(Loc.t("Some files could not be changed. Try again."));}
 static List<File> volumes(DownloadStore store){List<File> result=new ArrayList<>();result.add(store.directory);for(File f:store.storageDirectories())try{File parent=f.getParentFile();if(Environment.isExternalStorageRemovable(parent)&&!result.contains(f))result.add(f);}catch(Exception ignored){}return result;}
 static String volume(DownloadStore store,File f){return f.getParentFile().equals(store.directory)?"Phone storage":"SD card";}
 static void confirm(Activity a,String title,List<Saved> files,boolean watched,Runnable changed){PhoneDownloadsManage manager=new PhoneDownloadsManage(NoirApp.data,NoirApp.downloads);List<Saved> chosen=new ArrayList<>();long n=0;for(Saved f:files)if(!watched||f.watched()){chosen.add(f);n+=f.bytes;}NoirSheet s=new NoirSheet(a,title,Loc.f("%d videos · %s",chosen.size(),ltr(size(n))));s.note("Deletes permanently. Poster and watch history stay.");s.footer("Delete",()->run(a,()->manager.delete(chosen,watched),changed),"Cancel",null);s.show();}
 interface Work {long run()throws Exception;}
 static void run(Activity a,Work work,Runnable changed){DataStore owner=NoirApp.data;owner.images.execute(()->{try{long freed=work.run();a.runOnUiThread(()->{Toast.makeText(a,Loc.f("Freed %s",ltr(size(freed))),Toast.LENGTH_SHORT).show();changed.run();});}catch(Exception e){a.runOnUiThread(()->{Toast.makeText(a,e.getMessage(),Toast.LENGTH_LONG).show();changed.run();});}});}
 static void menu(Activity a,String title,List<Saved> files,boolean season,Runnable changed){NoirSheet s=new NoirSheet(a,title,Loc.f("%d videos · %s",files.size(),ltr(size(total(files)))));s.action("✕",title.equals(Loc.t("Movies"))?"Delete":season?"Delete season":"Delete show",null,()->confirm(a,"Delete saved videos?",files,false,changed));s.action("✓","Delete watched",null,()->confirm(a,"Delete watched",files,true,changed));moves(a,s,files,changed);s.show();}
 static long total(List<Saved> files){long n=0;for(Saved f:files)n+=f.bytes;return n;}
 static void moves(Activity a,NoirSheet s,List<Saved> files,Runnable changed){DownloadStore store=NoirApp.downloads;List<File> volumes=volumes(store);if(volumes.size()<2)return;for(File target:volumes){boolean needed=false;for(Saved f:files)if(!f.file.getParentFile().equals(target))needed=true;if(!needed)continue;s.action("⇄",target.equals(store.directory)?"Move to phone storage":"Move to SD card",null,()->move(a,files,target,changed));}}
 static void move(Activity a,List<Saved> files,File target,Runnable changed){DownloadStore store=NoirApp.downloads;NoirSheet progress=new NoirSheet(a,target.equals(store.directory)?"Move to phone storage":"Move to SD card",null);TextView label=progress.note(Loc.f("Moving… %s / %s","0 B",ltr(size(total(files)))));progress.dialog.setCancelable(false);progress.show();DataStore owner=NoirApp.data;owner.images.execute(()->{try{target.mkdirs();if(new android.os.StatFs(target.getAbsolutePath()).getAvailableBytes()<total(files)+32L*1024*1024)throw new IOException(Loc.t("Not enough space. Free some space on the destination and try again."));long done=0;for(Saved f:files){if(!store.file(f.id(),false).getCanonicalFile().equals(f.file.getCanonicalFile()))throw new IOException(Loc.t("Phone profile changed"));long base=done;store.relocate(f.id(),target,n->a.runOnUiThread(()->label.setText(Loc.f("Moving… %s / %s",ltr(size(base+n)),ltr(size(total(files)))))));done+=f.bytes;}a.runOnUiThread(()->Toast.makeText(a,Loc.t("Move complete"),Toast.LENGTH_SHORT).show());}catch(Exception e){a.runOnUiThread(()->Toast.makeText(a,e.getMessage(),Toast.LENGTH_LONG).show());}finally{a.runOnUiThread(()->{progress.dismiss();changed.run();});}});}
 static void freeSheet(Activity a,Runnable changed){PhoneDownloadsManage m=new PhoneDownloadsManage(NoirApp.data,NoirApp.downloads);DataStore owner=NoirApp.data;owner.images.execute(()->{List<Suggestion> choices=m.suggestions(System.currentTimeMillis());a.runOnUiThread(()->{if(a.isFinishing())return;NoirSheet s=new NoirSheet(a,"Free up space",null);Map<CheckBox,Suggestion> ticks=new LinkedHashMap<>();final View[] action={null};Runnable update=()->{long n=0;for(Map.Entry<CheckBox,Suggestion> e:ticks.entrySet())if(e.getKey().isChecked())n+=e.getValue().bytes();if(action[0] instanceof TextView){((TextView)action[0]).setText(Loc.f("Delete %s",ltr(size(n))));action[0].setContentDescription(((TextView)action[0]).getText());}};for(Suggestion c:choices){CheckBox tick=s.check(Loc.t(c.kind)+" · "+ltr(size(c.bytes())),true,(v,on)->update.run());ticks.put(tick,c);if(!c.sharing.isEmpty())s.note("Stop sharing, keep file");}s.note("Deletes permanently. Poster and watch history stay.");action[0]=s.footerPrimary("Delete","Delete",()->{List<Suggestion> chosen=new ArrayList<>();for(Map.Entry<CheckBox,Suggestion> e:ticks.entrySet())if(e.getKey().isChecked())chosen.add(e.getValue());run(a,()->m.free(chosen),changed);});update.run();s.show();});});}
 static void storageSheet(Activity a){DownloadStore store=NoirApp.downloads;NoirSheet s=new NoirSheet(a,"Default download storage",null);for(File f:volumes(store))s.choice(f.equals(store.directory)?"Phone storage":"SD card",null,f.equals(store.defaultDirectory()),()->{try{store.defaultDirectory(f);}catch(Exception e){Toast.makeText(a,e.getMessage(),Toast.LENGTH_LONG).show();}});s.show();}
}
